apply:
(s) => { const w = num(s.wue); const evap = !(s.coolingType === "liquid" || s.coolingType === "air" || (w !== null && w <= 0.05));
   if (!evap) return { ...s };
   return { ...s, wue: String(Math.min(w !== null ? w : 0.2, 0.2)), coolingType: "liquid",
     pue: num(s.pue) ? (num(s.pue) * 1.10).toFixed(2) : "1.43" }; }

(s) => { const w = num(s.wue); const evap = !(s.coolingType === "air" || (w !== null && w <= 0.05));
   if (!evap) return { ...s };
   return { ...s, wue: "0", coolingType: "air", heatRejectMethod: "air",
     pue: num(s.pue) ? (num(s.pue) * 1.25).toFixed(2) : "1.63" }; }
